from itertools import product

# Generate all possible binary sequences of length 23
sequences = list(product([-1, 1], repeat=23))

# Filter sequences based on the given constraints
valid_sequences = []
for seq in sequences:
    if seq[5] == -1 and seq[10] == -1 and seq[13] == 1 and seq[19] == 1:
        c = [0] * 23
        for k in range(1, 23):
            c_k = sum(seq[i] * seq[i + k] for i in range(23 - k))
            c[k] = c_k
        if c[12] == 0 and c[13] == -3 and c[16] == 0 and c[19] == -1:
            if sum(c_k ** 2 for c_k in c[1:]) <= 59:
                valid_sequences.append(seq)

# Check if any valid sequence exists
if valid_sequences:
    print(valid_sequences[0])
else:
    print("UNSATISFIABLE")
